export default {"P000547":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000547</code></p><h3>Closed immersion</h3><p>An isomorphism onto a closed subscheme of the target, with its specified scheme structure.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01HK\">Stacks 01HK · closed immersions</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01HK\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000547\">Open shared record</a></p></article>","P000562":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Topological spaces · compound · <code>P000562</code></p><h3>Connected space (Stacks convention)</h3><p>The space has a point and admits no partition into two nonempty open subsets.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/004S\">Stacks 004S · connectedness · Stacks 004S · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-004S\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000562\">Open shared record</a></p></article>","P000513":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Sites and presentations · predicate · <code>P000513</code></p><h3>Crystal in finite locally free modules</h3><p>The sheaf is a crystal in quasi-coherent modules and is finite locally free on the crystalline site.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/07IU\">Stacks 07IU · quasi-coherent and finite locally free crystals · Stacks 07IU · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/crystalline/#tag-07IU\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/03DL\">Stacks 03DL · finite local freeness on a ringed site</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/sites-modules/#tag-03DL\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000513\">Open shared record</a></p></article>","P000512":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Sites and presentations · predicate · <code>P000512</code></p><h3>Crystal in quasi-coherent modules</h3><p>The restrictions <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi class=\"math-euler-script\" mathvariant=\"normal\">ℱ</mi><mi>T</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\mathcal F_T</annotation></semantics></math></span></span> are quasi-coherent, and every crystalline pullback comparison map is an isomorphism.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/07IU\">Stacks 07IU · quasi-coherent and finite locally free crystals · Stacks 07IU · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/crystalline/#tag-07IU\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/07IT\">Stacks 07IT · quasi-coherence criterion</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/crystalline/#tag-07IT\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000512\">Open shared record</a></p></article>","P000551":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · compound · <code>P000551</code></p><h3>Faithfully flat</h3><p>Flat and surjective.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01U3\">Stacks 01U3 · flatness</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01U3\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/01RZ\">Stacks 01RZ · surjectivity</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01RZ\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000551\">Open shared record</a></p></article>","P000552":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · compound · <code>P000552</code></p><h3>Faithfully flat and qc</h3><p>Flat, surjective and quasi-compact. This single morphism defines an fpqc cover.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/022A\">Stacks 022A · fpqc coverings</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topologies/#tag-022A\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000552\">Open shared record</a></p></article>","P000511":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Sites and presentations · predicate · <code>P000511</code></p><h3>Finite locally free module on a crystalline site</h3><p>Every crystalline object admits a cover such that on each covering slice, <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi class=\"math-euler-script\" mathvariant=\"normal\">ℱ</mi></mrow><annotation encoding=\"application/x-tex\">\\mathcal F</annotation></semantics></math></span></span> is isomorphic to a finite direct sum of the restricted structure sheaf. The rank may vary between members of the cover.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/03DL\">Stacks 03DL · finite local freeness on a ringed site</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/sites-modules/#tag-03DL\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/07IU\">Stacks 07IU · quasi-coherent and finite locally free crystals</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/crystalline/#tag-07IU\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000511\">Open shared record</a></p></article>","P000548":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000548</code></p><h3>Immersion</h3><p>An isomorphism onto a locally closed subscheme of the target.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01IO\">Stacks 01IO · immersions</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01IO\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000548\">Open shared record</a></p></article>","P000545":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000545</code></p><h3>Isomorphism</h3><p>Has a two-sided inverse in the category of schemes.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/0017\">Stacks 0017 · isomorphisms in a category</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/categories/#tag-0017\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000545\">Open shared record</a></p></article>","P000550":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000550</code></p><h3>Monomorphism</h3><p>For every test scheme, two maps to the source with the same composite to the target coincide. Equivalently, the relative diagonal is an isomorphism.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01L3\">Stacks 01L3 · diagonal criterion</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01L3\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000550\">Open shared record</a></p></article>","P000559":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000559</code></p><h3>Noetherian source</h3><p>The source is a Noetherian scheme, so every subspace of its underlying space is quasi-compact.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01OV\">Stacks 01OV · Noetherian schemes</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/properties/#tag-01OV\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/04ZA\">Stacks 04ZA · subspaces of Noetherian spaces</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-04ZA\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000559\">Open shared record</a></p></article>","P000561":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Topological spaces · predicate · <code>P000561</code></p><h3>Nonempty space</h3><p>The underlying set has a point.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/004S\">Stacks 004S · nonemptiness in connectedness</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-004S\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000561\">Open shared record</a></p></article>","P000509":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Sites and presentations · predicate · <code>P000509</code></p><h3>Objectwise quasi-coherent crystalline module</h3><p>For every crystalline object <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\">(</mo><mi>U</mi><mo separator=\"true\">,</mo><mi>T</mi><mo separator=\"true\">,</mo><mi>δ</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">(U,T,\\delta)</annotation></semantics></math></span></span>, the restriction <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi class=\"math-euler-script\" mathvariant=\"normal\">ℱ</mi><mi>T</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\mathcal F_T</annotation></semantics></math></span></span> is quasi-coherent over <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi class=\"math-euler-script\" mathvariant=\"normal\">𝒪</mi><mi>T</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\mathcal O_T</annotation></semantics></math></span></span>.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/07IS\">Stacks 07IS · three conditions on crystalline modules · Stacks 07IS · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/crystalline/#tag-07IS\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000509\">Open shared record</a></p></article>","P000546":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000546</code></p><h3>Open immersion</h3><p>An isomorphism onto an open subscheme of the target.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01HE\">Stacks 01HE · open immersions</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01HE\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000546\">Open shared record</a></p></article>","P000557":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · compound · <code>P000557</code></p><h3>Proper and quasi-projective</h3><p>Proper and quasi-projective over the same target.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01W1\">Stacks 01W1 · properness</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01W1\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/01VW\">Stacks 01VW · quasi-projective</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01VW\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000557\">Open shared record</a></p></article>","P000556":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · compound · <code>P000556</code></p><h3>Quasi-affine of finite type</h3><p>Quasi-affine and of finite type over the target.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01SK\">Stacks 01SK · quasi-affine</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01SK\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/01T1\">Stacks 01T1 · finite type</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01T1\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000556\">Open shared record</a></p></article>","P000510":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Sites and presentations · predicate · <code>P000510</code></p><h3>Quasi-coherent module on a crystalline site</h3><p>Every crystalline object admits a cover such that on each covering slice, <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi class=\"math-euler-script\" mathvariant=\"normal\">ℱ</mi></mrow><annotation encoding=\"application/x-tex\">\\mathcal F</annotation></semantics></math></span></span> is the cokernel of a map between direct sums of the restricted structure sheaf.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/07IS\">Stacks 07IS · three conditions on crystalline modules · Stacks 07IS · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/crystalline/#tag-07IS\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/03DL\">Stacks 03DL · quasi-coherence on a ringed site</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/sites-modules/#tag-03DL\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000510\">Open shared record</a></p></article>","P000549":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · compound · <code>P000549</code></p><h3>Quasi-compact immersion</h3><p>An immersion whose inverse image of every affine open of the target is quasi-compact.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01IO\">Stacks 01IO · immersions</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01IO\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/01K3\">Stacks 01K3 · quasi-compactness</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01K3\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000549\">Open shared record</a></p></article>","P000560":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000560</code></p><h3>Quasi-finite</h3><p>Of finite type with finite underlying fibres.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/02NH\">Stacks 02NH · finite fibres and quasi-finiteness</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-02NH\">Index</a> · <a href=\"https://link.springer.com/content/pdf/10.1007/978-3-658-30733-2_13.pdf#page=7\">Görtz &amp; Wedhorn, Algebraic Geometry I: Schemes, 2nd ed., Definition 12.14, p. 330. A finite-type morphism is quasi-finite precisely when all its fibres have finitely many points.</a></p><p class=\"algebra-links\"><a href=\"../database/#P000560\">Open shared record</a></p></article>","P000558":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · compound · <code>P000558</code></p><h3>Separated and qc</h3><p>Separated and quasi-compact as a morphism.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01KK\">Stacks 01KK · separatedness and quasi-separatedness</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01KK\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/01K3\">Stacks 01K3 · quasi-compactness</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01K3\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000558\">Open shared record</a></p></article>","P000555":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · compound · <code>P000555</code></p><h3>Separated and quasi-finite</h3><p>Separated and of finite type with finite underlying fibres.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01KK\">Stacks 01KK · separatedness and quasi-separatedness</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01KK\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/02NH\">Stacks 02NH · finite fibres and quasi-finiteness</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-02NH\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000555\">Open shared record</a></p></article>","P000554":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · compound · <code>P000554</code></p><h3>Universal homeomorphism of finite type</h3><p>A universal homeomorphism that is also of finite type.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/04DF\">Stacks 04DF · characterization of universal homeomorphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-04DF\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/01T1\">Stacks 01T1 · finite type</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01T1\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000554\">Open shared record</a></p></article>","P000553":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000553</code></p><h3>Universally submersive</h3><p>After every base change, the underlying map is surjective and equips the target with the quotient topology.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/040H\">Stacks 040H · universal submersiveness</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-040H\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000553\">Open shared record</a></p></article>"};
